<script setup>
import { ref } from 'vue';
defineProps({ courses: Array });
const emit = defineEmits(['edit', 'delete', 'remove-lesson']);
const expanded = ref(null);
const money = value => Number(value || 0).toLocaleString('fr-CH', { minimumFractionDigits: 2 });
const date = value => new Date(`${value}T12:00:00`).toLocaleDateString('fr-CH');
</script>
<template><section class="overflow-hidden rounded-3xl bg-white"><div class="border-b border-black/5 px-6 py-5"><h2 class="font-serif text-2xl">Tous les cours</h2><p class="mt-1 text-xs text-black/45">{{ courses.length }} cours configurés</p></div><div class="overflow-x-auto"><table class="w-full min-w-[1100px] text-left"><thead class="bg-[#f7f5f0] text-[11px] font-bold uppercase tracking-wider text-black/45"><tr><th class="px-5 py-4">Cours</th><th class="px-5 py-4">Saison</th><th class="px-5 py-4">Horaire et lieu</th><th class="px-5 py-4">Capacité</th><th class="px-5 py-4">Tarifs</th><th class="px-5 py-4">Statut</th><th class="px-5 py-4 text-right">Actions</th></tr></thead><tbody class="divide-y divide-black/5"><template v-for="course in courses" :key="course.id"><tr class="align-middle hover:bg-[#faf9f6]"><td class="px-5 py-5"><div class="flex items-center gap-3"><img :src="course.image" :alt="course.title" class="h-14 w-16 rounded-xl object-cover" /><div><strong>{{ course.title }}</strong><p class="mt-1 text-xs text-black/40">{{ course.style }} · {{ course.level }} · {{ course.teacher }}</p><span v-if="course.couple_mode" class="mt-1 inline-block text-[10px] font-bold uppercase text-purple-700">Lead/Follow · écart {{ course.max_role_gap }}</span></div></div></td><td class="px-5 py-5"><strong class="text-sm">{{ course.season?.name || 'Non attribuée' }}</strong><p class="mt-1 text-xs text-black/40">{{ date(course.start_date) }} – {{ date(course.end_date) }}</p></td><td class="px-5 py-5"><strong class="text-sm">{{ course.day }} · {{ course.time }}</strong><p class="mt-1 text-xs text-black/40">{{ course.location }}</p></td><td class="px-5 py-5"><strong>{{ course.places }} / {{ course.capacity }}</strong><p class="text-xs text-black/40">places disponibles</p></td><td class="px-5 py-5"><strong>{{ money(course.session_price) }} CHF</strong><p class="text-xs" :class="course.trial_is_free ? 'text-green-700' : 'text-amber-700'">{{ course.trial_is_free ? 'Essai gratuit' : `Essai ${money(course.trial_price)} CHF` }}</p></td><td class="px-5 py-5"><span class="rounded-full px-3 py-1.5 text-[10px] font-bold uppercase" :class="course.is_active ? 'bg-green-50 text-green-700' : 'bg-black/5 text-black/40'">{{ course.is_active ? 'Publié' : 'Brouillon' }}</span></td><td class="px-5 py-5"><div class="flex justify-end gap-2"><button @click="expanded = expanded === course.id ? null : course.id" class="rounded-full border border-black/10 px-3 py-2 text-xs font-bold">{{ course.lessons.length }} leçons</button><button @click="emit('edit', course)" class="grid h-9 w-9 place-items-center rounded-full bg-black/5" title="Modifier">✎</button><button @click="emit('delete', course)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500" title="Supprimer">×</button></div></td></tr><tr v-if="expanded === course.id"><td colspan="7" class="bg-[#f7f5f0] px-6 py-5"><div class="mb-3"><strong>Calendrier des leçons</strong><p class="text-xs text-black/40">Retirez les vacances ou fermetures.</p></div><div class="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><div v-for="lesson in course.lessons" :key="lesson.id" class="flex items-center justify-between rounded-xl bg-white px-3 py-2 text-sm"><span>{{ date(lesson.lesson_date) }}</span><button @click="emit('remove-lesson', course, lesson)" class="text-red-500">×</button></div></div></td></tr></template></tbody></table></div><div v-if="!courses.length" class="px-6 py-16 text-center text-black/40">Aucun cours.</div></section></template>
